def family_init(ctx):
    import math
    bars = ctx.bars
    N = len(bars)
    hi = [float(b["h"]) for b in bars]
    lo = [float(b["l"]) for b in bars]
    P = max(4, int(ctx.p.period))
    delta = float(ctx.p.delta)
    fr = float(ctx.p.fraction)
    PA = max(5, int(ctx.p.pv_avg))

    ang = 4.0 * math.pi * delta / P
    if ang > 1.45:
        ang = 1.45
    if ang < 1e-4:
        ang = 1e-4
    beta = math.cos(2.0 * math.pi / P)
    gamma = 1.0 / math.cos(ang)
    alpha = gamma - math.sqrt(gamma * gamma - 1.0)

    pr = [(hi[j] + lo[j]) * 0.5 for j in range(N)]
    bp = [0.0] * N
    ca = 0.5 * (1.0 - alpha)
    cb = beta * (1.0 + alpha)
    for j in range(2, N):
        bp[j] = ca * (pr[j] - pr[j - 2]) + cb * bp[j - 1] - alpha * bp[j - 2]

    W = 2 * P
    mean = [None] * N
    s = 0.0
    for j in range(N):
        s += bp[j]
        if j >= W:
            s -= bp[j - W]
        if j >= W - 1:
            mean[j] = s / W

    pk = [0.0] * N
    vl = [0.0] * N
    cp = 0.0
    cv = 0.0
    for j in range(N):
        if j >= 2:
            b1 = bp[j - 1]
            if b1 > bp[j] and b1 > bp[j - 2]:
                cp = b1
            if b1 < bp[j] and b1 < bp[j - 2]:
                cv = b1
        pk[j] = cp
        vl[j] = cv

    ap = [None] * N
    avv = [None] * N
    s1 = 0.0
    s2 = 0.0
    for j in range(N):
        s1 += pk[j]
        s2 += vl[j]
        if j >= PA:
            s1 -= pk[j - PA]
            s2 -= vl[j - PA]
        if j >= PA - 1:
            ap[j] = s1 / PA
            avv[j] = s2 / PA

    md = [None] * N
    for j in range(N):
        m = mean[j]
        a = ap[j]
        v = avv[j]
        if m is None or a is None or v is None:
            continue
        if m > fr * a:
            md[j] = 1
        elif m < fr * v:
            md[j] = -1
        else:
            md[j] = 0

    ctx.bp = ctx.series(bp, "bandpass")
    ctx.ap = ctx.series(ap, "avgpeak")
    ctx.av = ctx.series(avv, "avgvalley")
    ctx.md = ctx.series(md, "mode")


def signal(ctx, i):
    if i < 1:
        return 0
    m = ctx.md[i]
    if m is None:
        return 0
    b = ctx.bp[i]
    pb = ctx.bp[i - 1]
    if b is None or pb is None:
        return 0
    if m == 1:
        return 1 if (pb <= 0.0 < b) else 0
    if m == -1:
        if int(ctx.p.dn_short) and pb >= 0.0 > b:
            return -1
        return 0
    a = ctx.ap[i]
    v = ctx.av[i]
    if a is None or v is None:
        return 0
    if pb <= v < b:
        return 1
    if pb >= a > b:
        return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions or i < 1:
        return False
    p = ctx.positions[0]
    ei = p["entry_i"]
    m0 = ctx.md[ei]
    m = ctx.md[i]
    b = ctx.bp[i]
    pb = ctx.bp[i - 1]
    if m0 is None or m is None or b is None or pb is None:
        return False
    if m0 == 1:
        return m != 1 or (pb >= 0.0 > b)
    if m0 == -1:
        return m != -1 or (pb <= 0.0 < b)
    if m != 0:
        return True
    if i - ei >= int(ctx.p.period):
        return True
    a = ctx.ap[i]
    v = ctx.av[i]
    if a is None or v is None:
        return False
    if p["side"] == "long":
        return pb >= a > b
    return pb <= v < b
